import{_ as s,a0 as p,w as l,s as r,ao as d,I as a,x as o,a1 as e,A as u}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const g=JSON.parse('{"title":"如何在手機上安裝Ubuntu Touch 13.10 | LCTT x X-CMD","titleTemplate":false,"description":"如何在手機上安裝Ubuntu Touch 13.10 | LCTT (201311) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"如何在手機上安裝Ubuntu Touch 13.10 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"如何在手機上安裝Ubuntu Touch 13.10 | LCTT (201311) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201311/How to Install Ubuntu Touch 13.10 on Your Phone","title":"如何在手機上安裝Ubuntu Touch 13.10","tag":"201311","desc":""},"relativePath":"201311/How to Install Ubuntu Touch 13.10 on Your Phone.md","filePath":"[post].md"}'),i={name:"201311/How to Install Ubuntu Touch 13.10 on Your Phone.md"};function T(b,t,h,m,c,f){const n=p("Link");return l(),r("div",null,[t[11]||(t[11]=d(`<h1 id="如何在手機上安裝ubuntu-touch-13-10" tabindex="-1">如何在手機上安裝Ubuntu Touch 13.10 <a class="header-anchor" href="#如何在手機上安裝ubuntu-touch-13-10" aria-label="Permalink to “如何在手機上安裝Ubuntu Touch 13.10”">​</a></h1><p><strong>Ubuntu Touch 13.10是Canonical公司針對手機新推出的一款操作系統，但是相對於桌面而言，它安裝到手機並不是那麼容易。</strong></p><p><img src="http://i1-news.softpedia-static.com/images/news2/How-to-Install-Ubuntu-Touch-13-10-On-Your-Phone-392828-2.jpg" alt=""></p><p>Canonical提供了安裝Ubuntu Touch 13.10所有必要的工具。這真是個好消息，因為手動安裝操作系統可是相當麻煩的。</p><p>首先提醒，此操作系統並非任何手機都能使用。因開發原因，Canonical限制其只能使用在Nexus 4設備上（代號金槍魚和灰鯖鯊） ，而且手機必須已被解鎖。</p><p>要安裝工具，你將需要在終端輸入幾個簡單的命令：</p><pre><code>sudo add-apt-repository ppa:phablet-team/tools
sudo apt-get update
sudo apt-get install phablet-tools android-tools-adb android-tools-fastboot
</code></pre><p>用户還必須確保他們的手機已被設置成開發使用。進入“設置項/關於手機”，點擊“軟件版本”7次。如果你操作正確，將會收到一條提示消息。</p><p>你必須從新菜單——“開發者選項”中啓用USB調試，該菜單通過前面的方法已被解鎖。在手機上勾選該選項時，會出現一條消息，通知用户正在配對。同意，那麼你準備得差不多了。</p><p>在開始安裝前的最後一步是備份你的Android系統。同樣使用adb工具。只要打開終端，輸入以下命令：</p><pre><code>adb backup -apk -shared -all
</code></pre><p>如果你要重新安裝原來的Android系統，打開一個終端，運行以下命令：</p><pre><code>adb restore backup.ab
</code></pre><p>最後的命令至關重要，你應該使用sudo運行，以確保正確執行該命令。打開一個終端，輸入以下命令：</p><pre><code>sudo phablet-flash ubuntu-system --no-backup
</code></pre><p>運行過程中應該沒有任何問題，設備將最終引導到Ubuntu Touch。不要停止終端也不要中斷此過程。</p><p>以上就是你需要遵照的簡單步驟，這樣，在所支持的設備上運作應該沒有任何問題了。</p><hr>`,18)),a("p",null,[t[1]||(t[1]=o("來源於: ",-1)),e(n,{href:"http://news.softpedia.com/news/How-to-Install-Ubuntu-Touch-13-10-On-Your-Phone-392828.shtml"},{default:u(()=>[...t[0]||(t[0]=[o("http://news.softpedia.com/news/How-to-Install-Ubuntu-Touch-13-10-On-Your-Phone-392828.shtml",-1)])]),_:1})]),a("p",null,[t[4]||(t[4]=o("譯者：",-1)),e(n,{href:"https://github.com/coolpigs"},{default:u(()=>[...t[2]||(t[2]=[o("coolpigs",-1)])]),_:1}),t[5]||(t[5]=o(" 校對：",-1)),e(n,{href:"https://github.com/carolinewuyan"},{default:u(()=>[...t[3]||(t[3]=[o("Caroline",-1)])]),_:1})]),a("p",null,[t[8]||(t[8]=o("本文由 ",-1)),e(n,{href:"https://github.com/LCTT/TranslateProject"},{default:u(()=>[...t[6]||(t[6]=[o("LCTT",-1)])]),_:1}),t[9]||(t[9]=o(" 原創翻譯，",-1)),e(n,{href:"http://linux.cn/"},{default:u(()=>[...t[7]||(t[7]=[o("Linux中國",-1)])]),_:1}),t[10]||(t[10]=o(" 榮譽推出",-1))])])}const w=s(i,[["render",T]]);export{g as __pageData,w as default};
